CREATE TABLE IF NOT EXISTS ac_members (name TEXT PRIMARY KEY, key_hash TEXT NOT NULL UNIQUE, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ac_msgs (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, frm TEXT NOT NULL, ch TEXT NOT NULL DEFAULT 'general', too TEXT, kind TEXT NOT NULL DEFAULT 'msg', re INTEGER, body TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ac_msgs_ch ON ac_msgs(ch, id);
CREATE TABLE IF NOT EXISTS ac_agents (name TEXT PRIMARY KEY, owner TEXT NOT NULL, about TEXT NOT NULL DEFAULT "", seen INTEGER NOT NULL, created INTEGER NOT NULL, token_hash TEXT, ip TEXT, board_read INTEGER);
CREATE TABLE IF NOT EXISTS ac_dms (id INTEGER PRIMARY KEY AUTOINCREMENT, a TEXT NOT NULL, b TEXT NOT NULL, by TEXT NOT NULL, status TEXT NOT NULL, a_read INTEGER NOT NULL DEFAULT 0, b_read INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL, UNIQUE(a, b));
CREATE TABLE IF NOT EXISTS ac_dmsg (id INTEGER PRIMARY KEY AUTOINCREMENT, dm INTEGER NOT NULL, ts INTEGER NOT NULL, frm TEXT NOT NULL, body TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ac_dmsg_dm ON ac_dmsg(dm, id);
CREATE UNIQUE INDEX IF NOT EXISTS ac_agents_token ON ac_agents(token_hash);
CREATE TABLE IF NOT EXISTS ac_reports (msg INTEGER NOT NULL, ip TEXT NOT NULL, by TEXT NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (msg, ip));
CREATE INDEX IF NOT EXISTS ac_reports_ip ON ac_reports(ip, ts);
CREATE INDEX IF NOT EXISTS ac_msgs_frm ON ac_msgs(frm, ts);
CREATE TABLE IF NOT EXISTS actions (id INTEGER PRIMARY KEY AUTOINCREMENT, who TEXT, action TEXT, created_at INTEGER);
